package dev.gbppimentel.zzz;
import java.util.*;
/** Focus outlines use diagonal connectivity: rounded one-pixel corners must stay joined. */
final class ControllerFocus {
 static boolean color(int[] pixels,int n){int c=pixels[n],r=c>>16&255,g=c>>8&255,b=c&255;return n%480>85&&n%480<435&&n/480>95&&n/480<238&&r>65&&g>60&&b<80&&r*10>g*5&&g*10>r*7&&g>b*1.5||r>130&&g>145&&b<80&&r*10>g*7&&g*10>r*7||n%480<110&&n/480>75&&n/480<237&&b>150&&b>r*1.5&&g>65;}
 static List<int[]> regions(int[] pixels){List<int[]> result=new ArrayList<>();boolean[] marked=new boolean[pixels.length];int[] queue=new int[pixels.length];for(int seed=0;seed<pixels.length;seed++){if(marked[seed]||!color(pixels,seed))continue;int head=0,tail=0,left=480,right=0,top=270,bottom=0;queue[tail++]=seed;marked[seed]=true;while(head<tail){int n=queue[head++],x=n%480,y=n/480;left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){int xx=x+dx,yy=y+dy;if(xx<0||xx>=480||yy<0||yy>=270)continue;int a=yy*480+xx;if(!marked[a]&&color(pixels,a)){marked[a]=true;queue[tail++]=a;}}}if(tail>=30&&right-left>=12&&bottom-top>=8)result.add(new int[]{left*4,top*4,(right+1)*4,(bottom+1)*4,tail});}return result;}
 static boolean outline(int c){int r=c>>16&255,g=c>>8&255,b=c&255;return r>65&&g>60&&b<90&&r*10>g*5&&g*10>r*7&&g>b*1.5;}
 static int[] travel(int[] pixels,boolean shortcut){int[] best=null;double high=.55;for(int i=0;i<(shortcut?6:9);i++){int l=shortcut?72+i*300:12+i%3*636,t=shortcut?938:102+i/3*278,r=shortcut?l+288:l+624,b=shortcut?1070:t+266,hit=0,total=0;for(int x=l+16;x<r-16;x+=4){for(int y:new int[]{t+3,b-5}){total++;if(outline(pixels[Math.min(269,y/4)*480+Math.min(479,x/4)]))hit++;}}for(int y=t+16;y<b-16;y+=4){for(int x:new int[]{l+3,r-5}){total++;if(outline(pixels[Math.min(269,y/4)*480+Math.min(479,x/4)]))hit++;}}double score=(double)hit/total;if(score>high){high=score;best=new int[]{l,t,r,b,hit};}}return best;}
 static int[] near(List<int[]> boxes,int x,int y){int[] best=null;double score=Double.MAX_VALUE;for(int[] b:boxes){if(y<700&&(x<440&&b[2]>450||x>450&&b[2]<450)||y>350&&b[3]<350||y>900&&b[3]<900)continue;int cx=(b[0]+b[2])/2,cy=(b[1]+b[3])/2;double candidate=Math.hypot(cx-x,cy-y)-Math.min(200,b[4]);if(candidate<score){best=b;score=candidate;}}return best;}
}
